import { useState } from "react";
import dynamic from "next/dynamic";
import clsx from "clsx";
import { StageProvider } from "../contexts.jsx";
import { Teaser } from "../teasers/layouts.jsx";
import { Button, Chevron } from "../ui/primitives.jsx";
import { Slider } from "../ui/Slider.jsx";
import { CommercialSlot, CompanionGroup, EsiFragment, StageHeader, StageSection } from "./parts.jsx";
import { interactionTracking } from "../../lib/tracking.js";
import { Box, Item } from "../ui/ds.jsx";

const ExclusiveStage = dynamic(() => import("./SliderStages.jsx").then((m) => m.ExclusiveStage));

function StandardStream({ stream }) {
    const [first, ...rest] = stream;
    return (
        <Box className="flex flex-col gap-(--teaser-gap)">
            {first ? <Teaser teaser={first.teaser} /> : null}
            <Box className="grid grid-cols-1 gap-x-6 gap-y-(--teaser-gap) desk:grid-cols-2">
                {rest.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
            </Box>
        </Box>
    );
}

function ClusterMore({ items }) {
    const [open, setOpen] = useState(false);
    return (
        <Box className="mt-4">
            {open ? (
                <Box className="grid grid-cols-1 gap-x-6 gap-y-(--teaser-gap) desk:grid-cols-2">
                    {items.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
                </Box>
            ) : null}
            <Box className="mt-4 flex justify-center">
                <Button variant="outline" aria-expanded={open} onClick={() => setOpen(!open)} {...interactionTracking("cluster-more")}>
                    {open ? "Weniger anzeigen" : "Mehr anzeigen"}
                    <Chevron open={open} />
                </Button>
            </Box>
        </Box>
    );
}

export function StandardStage({ stage }) {
    return (
        <StageSection stage={stage} label={stage.header.title?.label}>
            <StageHeader header={stage.header} />
            <Box className="grid grid-cols-1 gap-8 desk:grid-cols-[minmax(0,1fr)_18.75rem]">
                <Box>
                    <StandardStream stream={stage.stream} />
                    {stage.more ? <ClusterMore items={stage.more} /> : null}
                </Box>
                <aside className="flex flex-col gap-5">
                    {stage.esi?.map((tag) => <EsiFragment key={tag} tag={tag} />)}
                    {stage.companions.map((group) => <CompanionGroup key={group.index} group={group} />)}
                </aside>
            </Box>
        </StageSection>
    );
}

export function LeadStage({ stage }) {
    const [large, ...stream] = stage.stream;
    const cards = stream.filter((item) => item.teaser.layout === "card");
    const rest = stream.filter((item) => item.teaser.layout !== "card");
    return (
        <StageSection stage={stage} label="Top-Nachrichten" className="border-t-0 pt-0">
            <Box className="grid grid-cols-1 gap-8 desk:grid-cols-[minmax(0,1fr)_18.75rem]">
                <Box className="flex flex-col gap-(--teaser-gap)">
                    <Slider name="Top-Themen" label="Top-Themen" slideClassName="basis-full">
                        {stage.hero.map((teaser, i) => <Teaser key={teaser.id} teaser={teaser} priority={i === 0} />)}
                    </Slider>
                    <Teaser teaser={large.teaser} />
                    <Box className="grid grid-cols-1 gap-x-6 gap-y-(--teaser-gap) desk:grid-cols-2">
                        {rest.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
                    </Box>
                    <Box className="grid grid-cols-2 gap-4">
                        {cards.map((item) => <Teaser key={item.teaser.id} teaser={item.teaser} />)}
                    </Box>
                </Box>
                <aside className="flex flex-col gap-5">
                    <CompanionGroup group={stage.companions[0]} />
                    <CommercialSlot name="rectangle" sizes="300x250" minHeight={250} className="w-[300px]" />
                    {stage.companions.slice(1, 4).map((group) => <CompanionGroup key={group.index} group={group} />)}
                    <CommercialSlot name="native" sizes="354x624" lazy minHeight={624} className="w-full" />
                    {stage.companions.slice(4).map((group) => <CompanionGroup key={group.index} group={group} />)}
                </aside>
            </Box>
        </StageSection>
    );
}

function CommercialStage({ stage }) {
    return <CommercialSlot name={stage.slot} sizes="970x250,800x250,728x90" lazy={stage.slot !== "banner2"} minHeight={250} className="my-2 w-full max-w-[970px]" />;
}

const STAGES = {
    lead: LeadStage,
    standard: StandardStage,
    exclusive: ExclusiveStage,
    commercial: CommercialStage,
};

export function Stages({ stages }) {
    return (
        <Box className="flex flex-col gap-(--stage-gap)">
            {stages.map((stage) => {
                const Stage = STAGES[stage.layout];
                return (
                    <StageProvider key={stage.index} stage={stage}>
                        <Stage stage={stage} />
                    </StageProvider>
                );
            })}
        </Box>
    );
}

